CREATE TABLE IF NOT EXISTS material_offers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),material_id uuid NOT NULL REFERENCES materials(id),buyer_user_id text NOT NULL,seller_user_id text NOT NULL,quantity numeric NOT NULL,offer_price numeric NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','countered','accepted','declined','withdrawn')),last_actor text NOT NULL CHECK (last_actor IN ('buyer','seller')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(material_id,buyer_user_id));